<section class="panel narrow"><h2>Official company contact details</h2><p>Only enter verified company details. Saved details are published on the homepage.</p><form action="<?= site_url('settings') ?>" method="post"><?= csrf_field() ?><?php foreach(['contact_email'=>'Official email','contact_phone'=>'Official phone','office_address'=>'Office address'] as $key=>$label): ?><label><?= esc($label) ?><input name="<?= $key ?>" type="<?= $key==='contact_email'?'email':'text' ?>" value="<?= esc($settings[$key]??'','attr') ?>" maxlength="<?= $key==='contact_phone'?50:254 ?>"></label><?php endforeach ?><button type="submit">Save official details</button></form></section>
